// ── Helpers ──

// Diagnostic-only observations. Every original assertion and command is retained.
type GitObservation = Record<string, unknown>;
const gitObservations: GitObservation[] = [];
const activeObservedGit = new Map<number, GitObservation>();
const observedDirectories = new Map<string, string>();
let nextObservedCommand = 0;
let droppedGitObservations = 0;
const observedDirectory = (cwd: string) => {
  let label = observedDirectories.get(cwd);
  if (!label) {
    label = `owned-directory-${observedDirectories.size + 1}`;
    observedDirectories.set(cwd, label);
  }
  return label;
};
function traceGitObservation(kind: string, fields: GitObservation = {}) {
  if (gitObservations.length >= 4096) {
    droppedGitObservations++;
    return;
  }
  gitObservations.push({
    kind,
    at: performance.now(),
    ...fields,
    activeCommands: [...activeObservedGit.keys()],
  });
}
function observeGitExecution(execute: GitCoreShape["execute"]): GitCoreShape["execute"] {
  return (input) =>
    Effect.gen(function* () {
      const id = ++nextObservedCommand;
      const startedAt = performance.now();
      const context = {
        id,
        operation: input.operation,
        command: input.args[0] ?? null,
        directory: observedDirectory(input.cwd),
      };
      activeObservedGit.set(id, context);
      traceGitObservation("command-start", context);
      return yield* Effect.suspend(() => execute(input)).pipe(
        Effect.onExit((exit) =>
          Effect.sync(() => {
            activeObservedGit.delete(id);
            traceGitObservation("command-finish", {
              ...context,
              elapsedMs: performance.now() - startedAt,
              exit: exit._tag,
            });
          }),
        ),
      );
    });
}
afterAll(() => {
  traceGitObservation("outer-afterAll", {
    remaining: [...activeObservedGit.values()],
  });
  console.log(
    "SYNARA_GIT_COMMAND_OBSERVATIONS " +
      JSON.stringify({
        events: gitObservations,
        dropped: droppedGitObservations,
        activeAtEnd: [...activeObservedGit.values()],
        qualification:
          "Read-only delegated Git command and fixture-scope observations. No command, timer, cancellation, cleanup, or test assertion is replaced.",
      }),
  );
});

const GitCoreTestLayer = Layer.effect(
  GitCore,
  Effect.gen(function* () {
    const real = yield* GitCore;
    return yield* makeGitCore({ executeOverride: observeGitExecution(real.execute) });
  }),
).pipe(
  Layer.provide(GitCoreLive),
  Layer.provide(ServerConfigLayer),
  Layer.provide(NodeServices.layer),
);

